export const WASTE_RECYCLING_ACTIVITIES = [
{n:1,type:"mcq",micro:"Apa itu sampah",q:"Sampah adalah...",options:["barang sisa yang sudah tidak dipakai & dibuang oleh pemiliknya","semua benda yang ada di dalam rumah, baik yang masih dipakai maupun yang tidak dipakai","barang baru yang masih terbungkus rapi & belum pernah dipakai oleh pemiliknya sama sekali"],answer:0,explain:"Sampah muncul dari sisa kegiatan manusia; jumlahnya terus bertambah bila tidak dikelola.",hint:"Barang sisa yang dibuang."},
{n:2,type:"mcq",micro:"Ke mana sampah pergi",q:"Sebagian besar sampah rumah tangga di kota berakhir di...",options:["dibakar habis sampai tidak tersisa apa pun sehingga tidak perlu tempat pembuangan lagi","Tempat Pembuangan Akhir (TPA) berupa tumpukan besar","laut lepas yang dibuang langsung oleh petugas dari truk sampah setiap harinya"],answer:1,explain:"TPA menampung sampah bercampur; lahannya terbatas & bisa mencemari tanah & air bila tidak dikelola baik.",hint:"TPA / tempat pembuangan akhir."},
{n:3,type:"mcq",micro:"Mengapa sampah berlebih jadi masalah",q:"Terlalu banyak sampah menimbulkan masalah karena...",options:["tidak ada masalah sama sekali karena bumi ini cukup luas untuk menampung semua sampah kita","hanya mengganggu pemandangan sebentar saja & setelah itu hilang dengan sendirinya seperti biasa","lahan TPA cepat penuh, mencemari lingkungan, & sebagian sulit terurai"],answer:2,explain:"Sampah menumpuk mencemari tanah, air, & udara, serta menghabiskan lahan & biaya.",hint:"Lahan penuh + pencemaran + sulit terurai."},
{n:4,type:"mcq",micro:"Arti 3R",q:"3R dalam pengelolaan sampah adalah...",options:["Reduce (kurangi), Reuse (pakai ulang), Recycle (daur ulang)","Rapikan, Rebus, Rawat","Robek, Remas, Racik"],answer:0,explain:"3R adalah urutan tindakan mengurangi dampak sampah, dari yang paling utama.",hint:"Kurangi, pakai ulang, daur ulang."},
{n:5,type:"mcq",micro:"R yang paling utama",q:"Di antara 3R, yang paling utama dilakukan lebih dulu adalah...",options:["tidak ada urutan prioritas karena ketiganya sama pentingnya & boleh dilakukan dengan urutan apa saja","Reduce, yaitu mengurangi jumlah sampah yang kita hasilkan","Recycle, karena semua jenis sampah bisa didaur ulang dengan mudah dan tanpa dampak apa pun"],answer:1,explain:"Sampah yang tidak dihasilkan tidak perlu diangkut, diolah, atau ditimbun.",hint:"Mengurangi lebih baik daripada mengolah."},
{n:6,type:"tf",micro:"Sampah organik & anorganik",q:"Benar atau Salah: Sisa makanan & daun termasuk sampah organik, sedangkan plastik & kaleng termasuk sampah anorganik.",answer:true,explain:"Sampah organik bisa membusuk & dikomposkan; sampah anorganik butuh didaur ulang atau ditangani khusus.",hint:"Organik membusuk, anorganik tidak."},
{n:7,type:"mcq",micro:"Contoh sampah anorganik",q:"Manakah yang termasuk sampah anorganik?",options:["kulit pisang","daun kering","botol plastik & kaleng minuman"],answer:2,explain:"Sampah anorganik tidak mudah terurai secara alami & sebaiknya dipilah untuk didaur ulang.",hint:"Plastik & logam."},
{n:8,type:"mcq",micro:"Sampah B3",q:"Baterai bekas, sisa obat, & lampu neon termasuk sampah...",options:["berbahaya & beracun (B3) yang perlu penanganan khusus, bukan dibuang ke tempat sampah biasa","organik","yang bisa langsung dikompos"],answer:0,explain:"Sampah B3 bisa mencemari & membahayakan; harus dikumpulkan di tempat khusus.",hint:"Berbahaya, butuh tempat khusus."},
{n:9,type:"mcq",micro:"Contoh reduce",q:"Contoh 'reduce' (mengurangi) dalam kehidupan sehari-hari:",options:["memakai kembali kantong belanja lama setiap kali pergi ke pasar atau swalayan terdekat","membawa botol minum sendiri agar tidak beli air kemasan","mengumpulkan botol plastik bekas di rumah supaya nanti dikirim ke tempat daur ulang"],answer:1,explain:"Reduce berarti mencegah sampah muncul sejak awal.",hint:"Mencegah sampah muncul."},
{n:10,type:"mcq",micro:"Contoh reuse",q:"Contoh 'reuse' (memakai ulang):",options:["membeli barang sekali pakai dalam jumlah banyak supaya tidak perlu repot mencucinya lagi","membakar sampah plastik di halaman rumah supaya jumlahnya berkurang dan tidak menumpuk","memakai toples selai kosong sebagai tempat pensil"],answer:2,explain:"Reuse memperpanjang umur sebuah barang sehingga tidak cepat jadi sampah.",hint:"Memakai lagi untuk fungsi lain."},
{n:11,type:"tf",micro:"Memilah dari sumbernya",q:"Benar atau Salah: Memilah sampah tidak ada gunanya bila dilakukan dari rumah; lebih baik semua dicampur dan dipilah nanti di TPA.",answer:false,explain:"Sebaliknya, sampah yang tercampur jauh lebih sulit & mahal diolah; memilah sejak dari sumber membuat daur ulang & kompos mungkin dilakukan.",hint:"Pilah dari sumber."},
{n:12,type:"mcq",micro:"Contoh recycle",q:"Contoh 'recycle' (daur ulang):",options:["mengumpulkan kertas bekas agar diolah menjadi kertas baru","memakai gelas kaca yang sama berkali-kali untuk minum setiap hari tanpa membeli yang baru","tidak membeli barang-barang yang berlebihan & hanya membeli yang benar-benar dibutuhkan saja"],answer:0,explain:"Recycle mengubah sampah menjadi bahan untuk produk baru, meski butuh energi & proses.",hint:"Diolah jadi bahan baru."},
{n:13,type:"tf",micro:"Kompos dari sisa dapur",q:"Benar atau Salah: Sisa sayur, kulit buah, & daun tidak bisa diolah menjadi apa pun & satu-satunya pilihan adalah membuangnya ke TPA.",answer:false,explain:"Sebaliknya, sisa organik itu bisa dikomposkan menjadi pupuk alami yang menyuburkan tanah & mengurangi sampah ke TPA.",hint:"Sisa organik bisa jadi pupuk."},
{n:14,type:"mcq",micro:"Plastik sekali pakai",q:"Sedotan, kantong kresek, & sendok plastik sekali pakai bermasalah karena...",options:["selalu bisa didaur ulang dengan sempurna sehingga tidak pernah menjadi sampah sama sekali","dipakai sebentar tetapi bertahan puluhan hingga ratusan tahun sebagai sampah","langsung hilang dengan sendirinya setelah dibuang ke tempat sampah dalam waktu beberapa hari"],answer:1,explain:"Waktu pemakaian sangat singkat dibanding waktu terurainya yang sangat lama.",hint:"Dipakai sebentar, jadi sampah sangat lama."},
{n:15,type:"open",micro:"Sampahmu sehari",q:"Perkirakan sampah yang kamu hasilkan dalam satu hari. Sebutkan dua jenis & satu cara menguranginya.",explain:"Menyadari sampah sendiri adalah langkah pertama untuk menguranginya.",hint:"Dua jenis sampah + satu cara mengurangi.",sample:"Dalam sehari aku menghasilkan bungkus jajan plastik & botol air kemasan. Cara menguranginya: aku bisa membawa bekal dari rumah dalam kotak makan & membawa botol minum sendiri yang diisi ulang, jadi dua sumber sampah itu berkurang banyak."},
{n:16,type:"mcq",micro:"Membawa tas belanja",q:"Membawa tas kain sendiri saat berbelanja termasuk...",options:["recycle","menambah sampah","reduce, karena mengurangi kebutuhan kantong plastik baru"],answer:2,explain:"Kebiasaan kecil ini mencegah banyak kantong plastik sekali pakai.",hint:"Mengurangi kantong plastik baru."},
{n:17,type:"tf",micro:"Tidak semua bisa didaur ulang",q:"Benar atau Salah: Tidak semua jenis plastik & kemasan bisa didaur ulang; sebagian berakhir di TPA atau mencemari lingkungan.",answer:true,explain:"Karena itu mengurangi & memakai ulang lebih diandalkan daripada sekadar berharap pada daur ulang.",hint:"Daur ulang ada batasnya."},
{n:18,type:"mcq",micro:"Sampah & banjir",q:"Membuang sampah ke selokan atau sungai sering menyebabkan...",options:["saluran air tersumbat sehingga terjadi banjir saat hujan","air jadi lebih bersih","tidak ada dampak"],answer:0,explain:"Sampah yang menyumbat saluran adalah salah satu penyebab utama banjir di kota.",hint:"Menyumbat saluran, memicu banjir."},
{n:19,type:"order",micro:"Memulai pilah sampah di kelas",q:"Urutkan langkah memulai pemilahan sampah di kelas:",items:["Sepakati jenis pilahan (organik, plastik, kertas) bersama","Siapkan & beri label tempat sampah terpisah","Ingatkan & contohkan cara memilah dengan benar","Atur pengumpulan rutin untuk kompos & daur ulang"],answer:[0,1,2,3],explain:"Sepakati jenis, sediakan wadah berlabel, biasakan, lalu atur pengumpulan.",hint:"Sepakati dulu, atur pengumpulan terakhir."},
{n:20,type:"mcq",micro:"Ringkasan",q:"Inti pengelolaan sampah yang baik adalah...",options:["serahkan semua urusan sampah kepada petugas kebersihan tanpa perlu memilah sedikit pun di rumah","utamakan mengurangi & memakai ulang, daur ulang bila bisa, & pilah sejak dari sumber","cukup membuang semua jenis sampah ke satu tempat sampah saja supaya praktis & tidak repot"],answer:1,explain:"Urutan 3R & pemilahan dari sumber mengurangi sampah yang berakhir di TPA & lingkungan.",hint:"Kurangi & pakai ulang dulu, pilah dari sumber."},
{n:21,type:"classify",micro:"Organik atau anorganik",q:"Kelompokkan setiap sampah:",items:["Kulit jeruk","Botol plastik air mineral","Ampas kopi","Kaleng susu"],groups:["Organik","Anorganik"],answer:{"Organik":["Kulit jeruk","Ampas kopi"],"Anorganik":["Botol plastik air mineral","Kaleng susu"]},explain:"Sampah organik berasal dari makhluk hidup & bisa membusuk/dikompos; anorganik dari bahan buatan & butuh didaur ulang atau ditangani khusus.",hint:"Bisa membusuk vs tidak."},
{n:22,type:"mcq",micro:"Hierarki pengelolaan sampah",q:"Urutan prioritas pengelolaan sampah dari yang paling baik:",options:["buang ke TPA > daur ulang > pakai ulang > kurangi","semua sama pentingnya","kurangi > pakai ulang > daur ulang > buang ke TPA"],answer:2,explain:"Semakin ke kiri, semakin sedikit sumber daya & pencemaran yang ditimbulkan.",hint:"Kurangi paling utama, buang paling akhir."},
{n:23,type:"mcq",micro:"Mengapa reduce mengalahkan recycle",q:"Mengurangi konsumsi lebih baik daripada mengandalkan daur ulang karena...",options:["daur ulang tetap butuh energi, air, & sering menurunkan mutu bahan, sedangkan mengurangi tidak menimbulkan itu semua","daur ulang selalu gagal menghasilkan barang yang bagus, sedangkan mengurangi konsumsi tidak berpengaruh apa pun pada jumlah sampah yang dihasilkan manusia setiap hari","daur ulang tidak butuh energi, air, ataupun bahan tambahan sama sekali, sehingga kita boleh memakai & membuang barang sebanyak apa pun tanpa dampak pada lingkungan"],answer:0,explain:"Daur ulang penting, tetapi bukan solusi tanpa biaya; mencegah sampah lebih hemat sumber daya.",hint:"Daur ulang tetap butuh energi & menurunkan mutu."},
{n:24,type:"tf",micro:"Sampah daur ulang harus bersih",q:"Benar atau Salah: Wadah plastik atau kaleng yang berisi sisa makanan boleh langsung dimasukkan ke sampah daur ulang tanpa dibilas.",answer:false,explain:"Sebaliknya, sisa makanan bisa mencemari & menggagalkan proses daur ulang; satu wadah kotor bisa merusak satu bal sampah daur ulang.",hint:"Bilas dulu sebelum didaur ulang."},
{n:25,type:"mcq",micro:"Waktu terurai",q:"Dibanding kulit pisang yang terurai dalam hitungan minggu, botol plastik...",options:["tidak pernah menimbulkan masalah","butuh ratusan tahun untuk hancur & tidak benar-benar hilang, hanya jadi remah kecil","terurai lebih cepat"],answer:1,explain:"Perbedaan waktu terurai inilah kenapa sampah plastik menumpuk di lingkungan.",hint:"Ratusan tahun, jadi remah kecil."},
{n:26,type:"mcq",micro:"Mikroplastik",q:"Mikroplastik adalah...",options:["jenis plastik khusus berukuran besar yang aman dimakan manusia, cepat terurai sempurna, & tidak pernah ditemukan di air, tanah, maupun makanan kita","potongan logam sangat kecil yang berasal dari mesin pabrik yang berkarat, & hanya ditemukan di dalam tanah di sekitar pabrik saja, bukan di air atau makanan","potongan plastik sangat kecil yang berasal dari sampah plastik yang hancur & kini ditemukan di air, tanah, bahkan makanan"],answer:2,explain:"Plastik tidak hilang, hanya pecah menjadi partikel kecil yang menyebar ke rantai makanan.",hint:"Serpihan plastik sangat kecil di mana-mana."},
{n:27,type:"mcq",micro:"Sekali pakai vs pakai ulang",q:"Membandingkan gelas plastik sekali pakai & botol minum isi ulang:",options:["botol isi ulang menghasilkan jauh lebih sedikit sampah dalam jangka panjang meski awalnya perlu dibeli","keduanya sama saja","gelas sekali pakai lebih ramah lingkungan"],answer:0,explain:"Barang tahan lama yang dipakai berkali-kali mengalahkan barang sekali pakai dari sisi sampah.",hint:"Isi ulang lebih sedikit sampah jangka panjang."},
{n:28,type:"tf",micro:"Membakar sampah plastik",q:"Benar atau Salah: Membakar sampah plastik di halaman adalah cara aman & bersih untuk menghilangkannya.",answer:false,explain:"Sebaliknya, membakar plastik melepaskan asap beracun yang berbahaya bagi pernapasan & lingkungan.",hint:"Asap bakaran plastik itu beracun."},
{n:29,type:"mcq",micro:"Upcycling",q:"'Upcycling' berarti...",options:["membeli barang baru untuk menggantikan barang lama yang rusak supaya rumah tetap rapi & bagus","mengubah barang bekas menjadi barang baru yang nilainya lebih tinggi atau berguna","membuang barang lebih cepat dari biasanya agar rumah tidak penuh dan tampak lebih rapi"],answer:1,explain:"Contoh: ban bekas jadi pot tanaman, kaleng jadi lampu hias.",hint:"Barang bekas jadi lebih bernilai."},
{n:30,type:"mcq",micro:"E-waste",q:"Sampah elektronik (HP rusak, kabel, charger) sebaiknya...",options:["dibuang ke tempat sampah biasa bersama sampah dapur karena ukurannya cukup kecil untuk dibuang","dibakar bersama sampah lain di halaman supaya cepat habis & tidak memakan tempat di rumah","dikumpulkan ke tempat penerimaan e-waste karena mengandung bahan berharga & juga berbahaya"],answer:2,explain:"E-waste mengandung logam berharga yang bisa dipulihkan & zat berbahaya yang harus ditangani khusus.",hint:"Tempat penerimaan e-waste khusus."},
{n:31,type:"mcq",micro:"Terapan: pesta kelas",q:"Kelas mengadakan perayaan. Cara mengurangi sampah:",options:["pakai piring & gelas yang bisa dicuci, sediakan tempat sampah terpilah, & hindari balon serta sedotan plastik","memakai semua peralatan sekali pakai agar praktis & tidak perlu mencuci piring sesudah acara","tidak usah menyediakan tempat sampah sama sekali supaya orang membuang di mana saja mereka suka"],answer:0,explain:"Perencanaan sederhana bisa memangkas sebagian besar sampah acara.",hint:"Alat cuci-pakai + pilah + hindari sekali pakai."},
{n:32,type:"tf",micro:"Menolak yang tidak perlu",q:"Benar atau Salah: Menolak dengan sopan barang yang tidak kamu butuhkan (sedotan, kantong kecil, brosur) adalah bagian dari mengurangi sampah.",answer:true,explain:"'Refuse' atau menolak sering disebut sebagai R pertama sebelum reduce: sampah paling mudah diurus adalah yang tidak pernah kita ambil.",hint:"Menolak yang tak perlu = mengurangi."},
{n:33,type:"mcq",micro:"Terapan: sisa makanan kantin",q:"Banyak makanan terbuang di kantin sekolah. Solusi mengurangi:",options:["melarang semua orang makan di kantin sekolah supaya tidak ada lagi makanan yang terbuang","ambil porsi secukupnya, habiskan yang diambil, & kumpulkan sisa organik untuk kompos","mengambil makanan sebanyak-banyaknya lalu membuang yang tidak habis supaya tidak merasa kurang"],answer:1,explain:"Sampah makanan bisa dikurangi dari kebiasaan mengambil & menghabiskan, lalu mengompos sisanya.",hint:"Secukupnya, habiskan, kompos sisanya."},
{n:34,type:"mcq",micro:"Terapan: memperbaiki barang",q:"Tas sekolahmu jahitannya lepas sedikit. Pilihan paling hemat sampah:",options:["langsung membeli tas baru karena menjahit tas lama dianggap merepotkan dan tidak praktis","membuangnya begitu saja lalu memakai kantong plastik untuk membawa buku-buku ke sekolah","menjahitnya kembali atau memintanya diperbaiki"],answer:2,explain:"Memperbaiki memperpanjang umur barang & mencegah sampah sekaligus menghemat uang.",hint:"Perbaiki dulu sebelum membeli baru."},
{n:35,type:"mcq",micro:"Terapan: barang masih layak",q:"Kamu punya buku & mainan yang masih bagus tapi tidak dipakai lagi. Pilihan terbaik:",options:["memberikannya ke yang membutuhkan atau bank barang bekas, bukan membuangnya","membuangnya ke tempat sampah karena sudah tidak dipakai lagi & hanya memenuhi lemari saja","menyimpannya menumpuk di gudang sampai benar-benar rusak & tidak bisa dipakai oleh siapa pun"],answer:0,explain:"Barang yang masih berguna sebaiknya berpindah tangan, bukan menjadi sampah.",hint:"Berikan/donasikan yang masih layak."},
{n:36,type:"order",micro:"Membuat kompos sederhana",q:"Urutkan langkah membuat kompos dari sisa dapur di rumah:",items:["Siapkan wadah berlubang & alas tanah atau daun kering","Masukkan sisa sayur & buah, hindari daging & minyak","Aduk berkala & jaga kelembapannya","Setelah beberapa minggu, pakai kompos matang untuk tanaman"],answer:[0,1,2,3],explain:"Siapkan wadah, isi bahan yang tepat, rawat, lalu panen komposnya.",hint:"Siapkan wadah dulu, panen kompos terakhir."},
{n:37,type:"mcq",micro:"Terapan: belanja bekas",q:"Membeli seragam olahraga bekas layak pakai dari kakak kelas termasuk...",options:["menambah sampah","reuse yang mengurangi permintaan barang baru & sampah tekstil","pemborosan"],answer:1,explain:"Memberi kehidupan kedua pada barang mengurangi produksi & pembuangan.",hint:"Memakai ulang barang orang lain."},
{n:38,type:"open",micro:"Rencana 3R",q:"Pilih satu kegiatan sehari-harimu yang menghasilkan sampah. Tuliskan satu langkah reduce, satu reuse, & satu recycle untuk kegiatan itu.",explain:"Menerapkan ketiga R pada satu kebiasaan nyata membuat konsepnya jadi tindakan.",hint:"Satu langkah untuk tiap R pada satu kegiatan.",sample:"Kegiatan: jajan sepulang sekolah. Reduce: bawa uang pas & tolak kantong plastik, atau bawa bekal supaya tidak jajan berbungkus. Reuse: bawa wadah sendiri untuk membeli gorengan. Recycle: kumpulkan bungkus plastik bersih ke bank sampah sekolah untuk diolah menjadi ecobrick."},
{n:39,type:"mcq",micro:"Terapan: kemasan berlebih",q:"Saat membeli, memilih produk dengan kemasan lebih sedikit atau isi ulang berarti...",options:["tidak berpengaruh","selalu lebih mahal & sia-sia","mengurangi sampah kemasan sejak dari toko"],answer:2,explain:"Pilihan kita sebagai pembeli ikut menentukan berapa banyak sampah kemasan yang tercipta.",hint:"Pilih kemasan minimal / isi ulang."},
{n:40,type:"tf",micro:"Bank sampah",q:"Benar atau Salah: Bank sampah adalah tempat menyimpan uang tunai warga & tidak ada hubungannya dengan pengelolaan sampah.",answer:false,explain:"Sebaliknya, bank sampah adalah tempat warga menyetor sampah anorganik terpilah untuk ditukar dengan tabungan, sekaligus memastikan sampah itu didaur ulang.",hint:"Setor sampah terpilah, dapat tabungan."},
{n:41,type:"mcq",micro:"Terapan: acara lomba sekolah",q:"Sebagai panitia lomba, cara menekan sampah air kemasan:",options:["sediakan galon isi ulang & minta peserta membawa botol sendiri","membagikan ratusan botol plastik kecil kepada peserta supaya mereka tidak kehausan di lapangan","melarang semua peserta minum selama lomba berlangsung supaya tidak ada sampah kemasan sama sekali"],answer:0,explain:"Titik pengisian air bersama memangkas ratusan botol sekali pakai dalam satu acara.",hint:"Galon isi ulang + bawa botol sendiri."},
{n:42,type:"mcq",micro:"Terapan: sampah di jalan",q:"Kamu selesai makan di perjalanan & tidak ada tempat sampah. Sikap yang benar:",options:["melempar bungkusnya ke semak-semak supaya tidak terlihat oleh orang yang lewat di sekitar situ","simpan bungkusnya di tas sampai menemukan tempat sampah","membuangnya saja di pinggir jalan karena nanti pasti ada petugas yang akan menyapunya"],answer:1,explain:"Menahan sampah sampai ada tempat yang benar adalah kebiasaan warga yang bertanggung jawab.",hint:"Bawa dulu sampai ketemu tempat sampah."},
{n:43,type:"mcq",micro:"Terapan: baterai bekas",q:"Kamu punya beberapa baterai remote yang habis. Cara membuangnya yang benar:",options:["buang ke tempat sampah dapur","kubur di halaman","kumpulkan di wadah terpisah & serahkan ke titik pengumpulan sampah B3"],answer:2,explain:"Baterai mengandung logam berat; membuangnya sembarangan mencemari tanah & air.",hint:"Titik pengumpulan sampah B3."},
{n:44,type:"tf",micro:"Kompos mengurangi sampah TPA",q:"Benar atau Salah: Sisa organik hanya sebagian sangat kecil dari sampah rumah tangga, sehingga mengompos di rumah hampir tidak memengaruhi jumlah sampah ke TPA.",answer:false,explain:"Sebaliknya, hampir separuh sampah rumah tangga adalah sisa organik, jadi mengompos di rumah bisa memangkas banyak sampah yang dikirim ke TPA.",hint:"Organik hampir separuh sampah rumah."},
{n:45,type:"mcq",micro:"Terapan: memberi contoh",q:"Cara efektif mengajak keluarga memilah sampah:",options:["menyiapkan wadah terpisah berlabel & menjelaskan manfaatnya, lalu konsisten mencontohkan","memarahi anggota keluarga yang lupa memilah sampah supaya mereka menjadi lebih disiplin lagi","melakukannya diam-diam sendirian tanpa memberi tahu anggota keluarga lain tentang manfaatnya"],answer:0,explain:"Kemudahan (wadah siap) + alasan yang jelas + teladan konsisten membuat kebiasaan baru menempel.",hint:"Wadah berlabel + jelaskan + contohkan."},
{n:46,type:"mcq",micro:"Terapan: kertas bekas",q:"Kertas yang hanya terpakai satu sisi sebaiknya...",options:["dibakar","dipakai lagi sisi kosongnya untuk corat-coret sebelum akhirnya didaur ulang","langsung dibuang"],answer:1,explain:"Memakai kembali sisi kosong adalah reuse; setelah benar-benar penuh baru masuk daur ulang.",hint:"Pakai sisi kosongnya dulu."},
{n:47,type:"mcq",micro:"Terapan: minyak jelantah",q:"Minyak goreng bekas (jelantah) sebaiknya tidak dibuang ke wastafel karena...",options:["tidak masalah karena air akan melarutkan minyaknya sehingga tidak ada yang tersumbat di pipa","membuat pipa menjadi lebih licin & lebih awet sehingga tidak mudah rusak dalam waktu lama","menyumbat & mencemari saluran air; lebih baik dikumpulkan untuk diolah menjadi sabun atau biodiesel"],answer:2,explain:"Jelantah mencemari air & menyumbat pipa; kini banyak tempat menerima jelantah untuk diolah.",hint:"Kumpulkan, jangan buang ke wastafel."},
{n:48,type:"tf",micro:"Sampah campur sulit diolah",q:"Benar atau Salah: Sampah organik yang tercampur dengan plastik & kaca jadi jauh lebih sulit & mahal untuk dikompos maupun didaur ulang.",answer:true,explain:"Pencampuran adalah musuh utama pengolahan sampah; memilah dari sumber adalah kuncinya.",hint:"Campur = sulit & mahal diolah."},
{n:49,type:"mcq",micro:"Terapan: ecobrick",q:"Ecobrick adalah...",options:["botol plastik yang diisi padat sampah plastik bersih & kering untuk dijadikan bahan bangunan atau furnitur sederhana","batu bata biasa","jenis sampah organik"],answer:0,explain:"Ecobrick 'mengunci' sampah plastik yang sulit didaur ulang agar tidak mencemari lingkungan, meski bukan solusi utama.",hint:"Botol diisi padat sampah plastik."},
{n:50,type:"mcq",micro:"Terapan: memilih hadiah",q:"Saat memberi hadiah ulang tahun teman, pilihan yang lebih ramah sampah:",options:["balon & konfeti sekali pakai yang membuat suasana ulang tahun terlihat sangat meriah sekali","barang yang berguna & tahan lama, dibungkus kertas bekas atau kain yang bisa dipakai lagi","banyak barang kecil sekali pakai yang dibungkus plastik berlapis-lapis supaya tampak mewah dan penuh"],answer:1,explain:"Pilihan kita saat memberi juga menentukan sampah yang tercipta.",hint:"Berguna, tahan lama, bungkus minim."},
{n:51,type:"mcq",micro:"Terapan: program daur ulang sekolah",q:"Kamu ingin memulai program pengumpulan kertas & botol di sekolah. Langkah awal yang penting:",options:["langsung menaruh kardus & botol bekas di lorong sekolah tanpa meminta izin kepada siapa pun","mengumumkan program itu lalu berharap semua orang akan mengerti sendiri cara mengikutinya","bicara dengan guru & pihak sekolah, cari mitra pengepul/bank sampah, & rencanakan tempat serta jadwal"],answer:2,explain:"Program berhasil bila ada dukungan sekolah, tempat penyaluran yang jelas, & sistem yang dipahami semua.",hint:"Izin + mitra penyalur + tempat & jadwal."},
{n:52,type:"order",micro:"Mengurangi sampah acara sekolah",q:"Urutkan langkah panitia menekan sampah pentas seni:",items:["Perkirakan jenis sampah yang akan muncul (makanan, kemasan, dekorasi)","Pilih alternatif minim sampah (alat cuci-pakai, dekorasi pakai ulang)","Sediakan titik pilah sampah dengan label jelas","Setelah acara, catat berapa banyak sampah & apa yang bisa lebih baik lain kali"],answer:[0,1,2,3],explain:"Perkirakan, cari alternatif, sediakan titik pilah, lalu evaluasi.",hint:"Perkirakan dulu, evaluasi terakhir."},
{n:53,type:"mcq",micro:"Terapan: sampah daur ulang tercampur",q:"Di tempat sampah 'daur ulang' sekolah, banyak orang memasukkan sampah makanan. Solusi:",options:["perjelas label & gambar, letakkan tempat sampah organik tepat di sebelahnya, & ingatkan lewat sosialisasi singkat","membongkar & memilah ulang isinya sendiri setiap hari tanpa membenahi sistem labelnya sama sekali","menghentikan seluruh program daur ulang di sekolah karena dianggap tidak berhasil dijalankan"],answer:0,explain:"Kesalahan memilah sering karena sistem kurang jelas, bukan orangnya; perbaiki sistemnya.",hint:"Perjelas label + tempat organik di sebelahnya."},
{n:54,type:"mcq",micro:"Terapan: kantong plastik menumpuk di rumah",q:"Rumahmu punya banyak kantong kresek bekas. Pemakaian ulang yang baik:",options:["membeli kantong kresek baru lagi karena harganya murah & mudah didapat di warung terdekat","memakainya lagi untuk belanja atau sebagai kantong sampah, & mulai membawa tas kain agar tidak bertambah","membuang semua kantong kresek bekas itu sekaligus supaya rumah menjadi bersih dan lapang"],answer:1,explain:"Reuse mengurangi kebutuhan kantong baru, & membawa tas kain mencegah tumpukan bertambah.",hint:"Pakai ulang + mulai bawa tas kain."},
{n:55,type:"mcq",micro:"Terapan: pakaian rusak",q:"Kaus lamamu sudah robek & tidak layak pakai. Pilihan minim sampah:",options:["langsung buang ke TPA","bakar di halaman","potong menjadi kain lap atau serahkan ke tempat daur ulang tekstil"],answer:2,explain:"Tekstil bisa dipakai ulang sebagai lap atau didaur ulang; membakarnya mencemari udara.",hint:"Jadikan lap atau daur ulang tekstil."},
{n:56,type:"open",micro:"Audit sampah kelas",q:"Bayangkan kelasmu melakukan 'audit sampah' selama seminggu. Tulis dua hal yang mungkin kalian temukan & satu perubahan yang bisa kalian usulkan.",explain:"Mengukur sampah sendiri memberi dasar untuk perubahan yang tepat sasaran.",hint:"Dua temuan + satu usulan perubahan.",sample:"Kemungkinan temuan: satu, sampah terbanyak adalah bungkus jajan plastik dari kantin. Dua, banyak kertas dibuang padahal baru dipakai satu sisi. Usulan perubahan: sediakan kotak kertas bekas untuk corat-coret, & ajak kantin menjual jajan dalam wadah yang bisa dikembalikan atau tanpa bungkus plastik."},
{n:57,type:"mcq",micro:"Terapan: menolak jajan berbungkus",q:"Kantin menawarkan jajan dalam plastik berlapis. Sikap konsumen yang sadar sampah:",options:["memilih jajan tanpa bungkus atau membawa wadah sendiri, & menyampaikan usulan ke pengelola kantin","tetap membelinya lalu membuang bungkusnya sembarangan karena sudah terbiasa melakukan hal itu","berhenti jajan selamanya karena kesal & tidak mau lagi menyampaikan usulan kepada pengelola"],answer:0,explain:"Pilihan & masukan konsumen bisa mendorong penjual mengurangi kemasan.",hint:"Pilih tanpa bungkus + beri masukan."},
{n:58,type:"tf",micro:"Perubahan kecil banyak orang",q:"Benar atau Salah: Meski seluruh murid di satu sekolah membawa botol minum sendiri, jumlah sampah botol plastik sekolah itu tidak akan berubah berarti.",answer:false,explain:"Sebaliknya, sampah adalah masalah akumulatif; perubahan kecil yang dilakukan banyak orang bisa menurunkan sampah botol plastik sekolah secara drastis.",hint:"Banyak orang, kebiasaan kecil, dampak besar."},
{n:59,type:"mcq",micro:"Terapan: donasi vs buang",q:"Sekolah mengumpulkan buku & seragam bekas. Sikap keluarga yang mendukung:",options:["menyimpan semuanya sampai bertumpuk di rumah & tidak pernah memilah mana yang masih layak","menyortir barang yang masih layak & menyumbangkannya, membuang hanya yang benar-benar rusak","membuang semua yang tidak dipakai lagi tanpa memeriksa mana yang sebenarnya masih bagus"],answer:1,explain:"Menyalurkan barang layak pakai memperpanjang manfaatnya & mengurangi sampah.",hint:"Sumbangkan yang layak, buang yang rusak saja."},
{n:60,type:"mcq",micro:"Terapan: sampah saat piknik keluarga",q:"Saat piknik, cara keluarga menekan sampah:",options:["membeli makanan dengan banyak bungkus lalu meninggalkan sampahnya di tempat piknik saja","membakar sampah di lokasi piknik supaya tempatnya terlihat bersih sebelum keluarga pulang","bawa bekal dalam kotak makan, botol isi ulang, & kantong untuk membawa pulang semua sampah"],answer:2,explain:"Merencanakan bekal & membawa pulang sampah menjaga tempat wisata tetap bersih.",hint:"Bekal wadah + bawa pulang sampah."},
{n:61,type:"mcq",micro:"Ekonomi linear vs melingkar",q:"'Ekonomi linear' (ambil-buat-buang) berbeda dari 'ekonomi melingkar' karena...",options:["ekonomi melingkar berusaha menjaga bahan tetap dipakai selama mungkin lewat perbaikan, pakai ulang, & daur ulang","keduanya sama","ekonomi melingkar membuang lebih banyak"],answer:0,explain:"Ekonomi melingkar meniru alam: sisa satu proses menjadi bahan untuk proses lain.",hint:"Menjaga bahan tetap terpakai, bukan sekali buang."},
{n:62,type:"mcq",micro:"Batas daur ulang",q:"Plastik yang didaur ulang sering...",options:["menjadi lebih kuat & lebih bagus mutunya setiap kali melalui proses daur ulang berikutnya","menurun mutunya setiap siklus sehingga akhirnya tetap menjadi sampah (downcycling)","bisa didaur ulang tanpa batas berkali-kali dengan mutu yang tetap sama seperti semula"],answer:1,explain:"Karena daur ulang bukan lingkaran sempurna, mengurangi pemakaian tetap yang paling penting.",hint:"Mutu turun tiap siklus."},
{n:63,type:"mcq",micro:"Tanggung jawab produsen",q:"Sebagian sampah kemasan bisa dikurangi bila...",options:["hanya konsumen yang perlu berubah sedangkan produsen tidak perlu mengubah cara membuat kemasan","tidak ada yang bisa dilakukan karena kemasan memang sudah seperti itu sejak dahulu kala","produsen merancang kemasan yang lebih sedikit, bisa diisi ulang, atau mudah didaur ulang"],answer:2,explain:"Keputusan desain produk di hulu sangat menentukan sampah di hilir; perubahan butuh peran produsen & kebijakan, bukan konsumen saja.",hint:"Desain kemasan di hulu penting."},
{n:64,type:"tf",micro:"Individu & sistem sama-sama perlu",q:"Benar atau Salah: Mengurangi sampah butuh kebiasaan individu sekaligus sistem yang mendukung (tempat pilah, layanan daur ulang, aturan kemasan).",answer:true,explain:"Kebiasaan baik sulit bertahan tanpa fasilitas; fasilitas sia-sia tanpa kebiasaan. Keduanya dibutuhkan.",hint:"Kebiasaan + sistem, keduanya."},
{n:65,type:"mcq",micro:"Biaya sampah ditanggung siapa",q:"Biaya mengangkut & mengolah sampah kota pada akhirnya ditanggung oleh...",options:["warga bersama, lewat pajak & retribusi, sehingga mengurangi sampah juga menghemat uang bersama","hanya pemerintah yang menanggungnya dari sumber dana yang entah datang dari mana saja","tidak ada yang menanggung karena layanan pengangkutan sampah itu pada dasarnya gratis"],answer:0,explain:"Semakin banyak sampah, semakin besar biaya yang ditanggung masyarakat.",hint:"Warga bersama, lewat pajak/retribusi."},
{n:66,type:"mcq",micro:"Dari darat ke laut",q:"Sampah plastik yang dibuang di darat bisa berakhir di laut karena...",options:["tidak mungkin sampai ke laut karena sampah di darat selalu tinggal diam di tempatnya","terbawa angin & air hujan ke selokan, lalu ke sungai, & akhirnya ke laut","laut menarik sampah itu dari jauh sehingga sampah berpindah sendiri ke arah pantai"],answer:1,explain:"Sebagian besar sampah plastik di laut berasal dari daratan lewat sungai.",hint:"Selokan > sungai > laut."},
{n:67,type:"mcq",micro:"Menyisakan lahan untuk yang lain",q:"Setiap ton sampah yang tidak jadi kita kirim ke TPA berarti...",options:["tidak ada bedanya","kerugian bagi petugas kebersihan","lahan & lingkungan yang sedikit lebih baik untuk orang & generasi berikutnya"],answer:2,explain:"Mengurangi sampah adalah bentuk merawat milik bersama lintas generasi.",hint:"Lahan lebih baik untuk yang berikutnya."},
{n:68,type:"tf",micro:"Daur ulang bukan izin boros",q:"Benar atau Salah: Fakta bahwa suatu barang 'bisa didaur ulang' bukan alasan untuk memakainya secara boros.",answer:true,explain:"Label 'dapat didaur ulang' tidak menjamin barang itu benar-benar didaur ulang; mengurangi tetap lebih pasti.",hint:"Bisa didaur ulang bukan berarti boleh boros."},
{n:69,type:"mcq",micro:"Memilih yang tahan lama",q:"Saat harus membeli barang, pilihan yang mengurangi sampah jangka panjang:",options:["barang yang kuat, bisa diperbaiki, & suku cadangnya tersedia","yang paling murah harganya walaupun cepat rusak & harus sering dibeli lagi dalam waktu dekat","yang modelnya sering berganti supaya kita selalu punya barang terbaru yang sedang populer"],answer:0,explain:"Barang tahan lama & bisa diperbaiki menghasilkan lebih sedikit sampah sepanjang waktu.",hint:"Kuat, bisa diperbaiki."},
{n:70,type:"order",micro:"Menerapkan hierarki sampah pada satu barang",q:"Urutkan cara menangani sebuah kantong plastik dari yang paling baik:",items:["Tolak / tidak mengambilnya sejak awal bila tidak perlu","Bila terlanjur ada, pakai berulang kali untuk berbagai keperluan","Bila sudah tidak layak, setor ke bank sampah untuk didaur ulang","Buang ke tempat sampah hanya bila tidak ada pilihan lain"],answer:[0,1,2,3],explain:"Tolak, pakai ulang, daur ulang, lalu terakhir buang.",hint:"Tolak paling baik, buang paling akhir."},
{n:71,type:"mcq",micro:"Mengapa 'membuang' bukan solusi akhir",q:"Kalimat 'sampah dibuang' sebenarnya kurang tepat karena...",options:["membuang selalu menyelesaikan masalah sampah karena sampah langsung hilang dari kehidupan kita","tidak ada tempat yang benar-benar 'jauh'; sampah tetap ada di suatu tempat & memengaruhi seseorang","sampah benar-benar lenyap sepenuhnya setelah dibuang ke tempat sampah atau ke selokan"],answer:1,explain:"'Membuang' hanya memindahkan masalah; karena itu mengurangi di awal jauh lebih efektif.",hint:"Tidak ada tempat yang benar-benar 'jauh'."},
{n:72,type:"mcq",micro:"Menilai gaya hidup dari sampah",q:"Cara sederhana menilai apakah gaya hidup kita makin ramah lingkungan:",options:["lihat seberapa penuh tempat sampah setiap hari tanpa memedulikan apa isi di dalamnya sama sekali","gaya hidup tidak bisa dinilai sama sekali karena tidak ada tanda yang bisa dilihat orang","perhatikan apakah tempat sampah kita makin sedikit terisi & makin banyak yang bisa dikompos atau didaur ulang"],answer:2,explain:"Volume & jenis sampah yang kita hasilkan adalah cermin kebiasaan konsumsi kita.",hint:"Perhatikan isi & jumlah tempat sampahmu."},
{n:73,type:"mcq",micro:"Sampah organik & gas",q:"Sampah organik yang menumpuk di TPA tanpa pengolahan menghasilkan gas metana yang...",options:["ikut memperparah pemanasan global bila tidak ditangkap","membuat udara di sekitar tempat pembuangan menjadi lebih segar & lebih baik untuk pernapasan","tidak berbahaya sama sekali bagi lingkungan, tubuh manusia, maupun cuaca bumi kita ini"],answer:0,explain:"Mengompos atau mengolah sampah organik terpisah mengurangi gas rumah kaca dari TPA.",hint:"Metana memperparah pemanasan global."},
{n:74,type:"open",micro:"Refleksi kebiasaan",q:"Tuliskan satu kebiasaan lama yang menghasilkan banyak sampah & satu kebiasaan baru yang ingin kamu jalankan selama sebulan ke depan.",explain:"Menargetkan satu perubahan yang jelas lebih mungkin berhasil daripada berjanji berubah total.",hint:"Satu kebiasaan lama + satu kebiasaan baru yang spesifik.",sample:"Kebiasaan lama: selalu membeli air minum dalam kemasan sekali pakai di sekolah, kadang dua botol sehari. Kebiasaan baru: membawa satu botol minum stainless yang kuisi dari rumah & isi ulang di sekolah. Aku akan menaruhnya di tas sejak malam supaya tidak lupa."},
{n:75,type:"tf",micro:"Bebas sampah sempurna itu perlu?",q:"Benar atau Salah: Untuk berdampak, kita tidak harus langsung 'nol sampah'; mengurangi secara bertahap & konsisten sudah sangat berarti.",answer:true,explain:"Perbaikan bertahap oleh banyak orang lebih berdampak daripada kesempurnaan yang dikejar segelintir orang lalu menyerah.",hint:"Bertahap & konsisten sudah berarti."},
{n:76,type:"mcq",micro:"Menghargai pemulung & pengepul",q:"Terhadap pemulung & pengepul yang mengambil botol serta kardus, sikap yang tepat:",options:["menyembunyikan sampah daur ulang dari mereka supaya tidak diambil oleh orang yang tidak dikenal","menghargai peran mereka dalam rantai daur ulang & memilah sampah agar lebih mudah mereka olah","menganggap pekerjaan mereka hina & rendah sehingga tidak perlu dihargai oleh warga lainnya"],answer:1,explain:"Mereka adalah bagian penting sistem daur ulang; memilah sampah membantu pekerjaan mereka.",hint:"Hargai perannya, pilah agar mudah."},
{n:77,type:"mcq",micro:"Sampah & kesehatan",q:"Sampah yang menumpuk & tidak terkelola bisa...",options:["tidak berpengaruh apa pun pada kesehatan warga sekitar karena sampahnya hanya diam di tempat","membuat lingkungan sekitar menjadi lebih sehat & bersih karena sampahnya menjadi pupuk alami","menjadi sarang penyakit, lalat, & tikus, serta mencemari sumber air warga"],answer:2,explain:"Pengelolaan sampah yang baik adalah bagian dari menjaga kesehatan masyarakat.",hint:"Sarang penyakit & pencemar air."},
{n:78,type:"mcq",micro:"Kebun & kompos sekolah",q:"Manfaat kebun sekolah yang memakai kompos buatan sendiri:",options:["mengurangi sampah organik, menghemat pupuk, & jadi sarana belajar langsung","hanya menghabiskan waktu","tidak ada gunanya"],answer:0,explain:"Kebun-kompos menutup lingkaran: sisa makanan kembali menyuburkan tanaman.",hint:"Kurangi sampah + hemat pupuk + belajar."},
{n:79,type:"mcq",micro:"Mengajak lewat data",q:"Cara meyakinkan sekolah memulai program pengurangan sampah:",options:["hanya mengatakan 'pokoknya program ini harus ada' tanpa menunjukkan alasan atau datanya sama sekali","tunjukkan data berapa banyak sampah dihasilkan & perkiraan penghematan biaya serta manfaat lingkungannya","memaksa pihak sekolah dengan ancaman akan mogok belajar jika program itu tidak segera dijalankan"],answer:1,explain:"Usulan dengan data & manfaat konkret lebih mungkin diterima pengambil keputusan.",hint:"Pakai data & perkiraan manfaat."},
{n:80,type:"mcq",micro:"Warga yang bijak sampah",q:"Gambaran warga yang bijak mengelola sampah:",options:["membuang semuanya ke satu tempat sampah lalu menyalahkan pemerintah kalau lingkungan menjadi kotor","hanya peduli pada sampah ketika ada lomba kebersihan lalu melupakannya setelah lomba itu selesai","mengurangi konsumsi, memakai ulang, memilah, mengompos, membuang pada tempatnya, & mengajak orang lain"],answer:2,explain:"Tanggung jawab atas sampah adalah kebiasaan sehari-hari yang menyeluruh.",hint:"Kurangi, pakai ulang, pilah, kompos, ajak."},
{n:81,type:"mcq",micro:"Skenario: kantin penuh styrofoam",q:"Kantin sekolah memakai wadah styrofoam untuk semua makanan. Langkah warga sekolah:",options:["ajukan usulan bersama agar kantin beralih ke wadah guna ulang atau daun/kertas, sambil membawa kotak makan sendiri","tetap membeli makanan di kantin lalu membuang wadah styrofoam-nya sembarangan seperti biasanya","memboikot kantin sekolah tanpa memberi usulan pengganti sehingga pengelola kantin tidak mengerti"],answer:0,explain:"Perubahan penyedia butuh usulan kolektif; sambil menunggu, kebiasaan pribadi tetap membantu.",hint:"Usulan bersama + bawa wadah sendiri."},
{n:82,type:"tf",micro:"Styrofoam sulit didaur ulang",q:"Benar atau Salah: Wadah styrofoam mudah didaur ulang di mana saja & cepat terurai di lingkungan.",answer:false,explain:"Sebaliknya, styrofoam sangat sulit didaur ulang & umumnya berakhir sebagai sampah yang bertahan sangat lama; menghindarinya (reduce) jauh lebih efektif.",hint:"Sulit didaur ulang, bertahan lama."},
{n:83,type:"mcq",micro:"Skenario: memulai kompos di rumah",q:"Orang tuamu ragu mengompos karena takut bau. Cara meyakinkan:",options:["menyerah & membuang semua sisa organik","jelaskan bahwa kompos yang benar (bahan tepat, diaduk, tidak terlalu basah) tidak bau, & mulai dari wadah kecil sebagai percobaan","memaksa mereka"],answer:1,explain:"Kekhawatiran umum bisa dijawab dengan informasi & percobaan kecil yang berhasil.",hint:"Jelaskan cara benar + mulai kecil."},
{n:84,type:"mcq",micro:"Skenario: banyak sisa makanan di acara",q:"Setelah acara sekolah, banyak nasi kotak tersisa masih layak makan. Tindakan terbaik:",options:["membuang semuanya ke tempat sampah sekaligus karena itu cara paling cepat & paling praktis","membiarkannya menumpuk begitu saja sampai basi & tidak bisa dimakan oleh siapa pun lagi","koordinasikan agar makanan layak dibagikan ke yang membutuhkan sebelum basi, sisanya dikompos"],answer:2,explain:"Mencegah makanan layak terbuang lebih baik daripada mengompos; kompos untuk yang benar-benar tak termakan.",hint:"Bagikan yang layak dulu, kompos sisanya."},
{n:85,type:"mcq",micro:"Skenario: elektronik lama menumpuk",q:"Di rumah ada tumpukan HP rusak, charger, & kabel lama. Langkah yang benar:",options:["kumpulkan & bawa ke titik pengumpulan e-waste atau program penjemputan, jangan campur ke sampah rumah","membuangnya ke tempat sampah biasa bersama sampah dapur supaya rumah cepat menjadi bersih","membakarnya sampai habis untuk memusnahkannya sehingga tidak ada lagi yang tersisa di rumah"],answer:0,explain:"E-waste butuh jalur khusus agar bahan berharganya dipulihkan & zat berbahayanya aman ditangani.",hint:"Titik pengumpulan e-waste."},
{n:86,type:"mcq",micro:"Skenario: teman membuang sampah dari mobil",q:"Kamu di dalam mobil & temanmu melempar bungkus ke jalan. Respons yang baik:",options:["diam saja karena itu bukan mobilmu & kamu tidak merasa berhak menegur teman sendiri sama sekali","tawarkan kantong sampah di mobil & ingatkan dengan santai bahwa sampah jalanan berakhir di selokan & sungai","ikut melempar sampahmu juga ke jalan supaya kamu tidak dianggap berbeda dari temanmu itu"],answer:1,explain:"Mengingatkan dengan cara yang tidak menghakimi & menyediakan solusi (kantong) lebih efektif.",hint:"Sediakan kantong + ingatkan santai."},
{n:87,type:"mcq",micro:"Skenario: program daur ulang berhenti di tengah jalan",q:"Program pilah sampah kelas berjalan seminggu lalu berantakan. Cara memperbaiki:",options:["menyimpulkan bahwa warga kelas memang tidak peduli sehingga program itu tidak perlu dilanjutkan","memulai program baru yang sama persis tanpa mengubah apa pun & berharap hasilnya akan berbeda","evaluasi bersama apa yang menyulitkan (label kurang jelas? tidak ada yang mengangkut?) & perbaiki satu per satu"],answer:2,explain:"Program lingkungan sering gagal karena hambatan praktis yang bisa diperbaiki, bukan karena orang tidak peduli.",hint:"Cari hambatan praktis & perbaiki."},
{n:88,type:"order",micro:"Kampanye kurangi plastik sekali pakai",q:"Urutkan langkah kampanye 'bawa botol sendiri' di sekolah:",items:["Kumpulkan data jumlah sampah botol plastik sekolah selama seminggu","Ajukan usulan & minta dukungan sekolah untuk titik isi ulang air","Sosialisasikan lewat poster, pengumuman, & contoh dari pengurus","Ukur lagi setelah sebulan & rayakan penurunannya"],answer:[0,1,2,3],explain:"Data dulu, dukungan & sarana, sosialisasi, lalu ukur hasilnya.",hint:"Data dulu, ukur hasil terakhir."},
{n:89,type:"mcq",micro:"Skenario: dilema kemasan saat sakit",q:"Kadang kemasan sekali pakai memang diperlukan (misalnya alasan kebersihan atau medis). Sikap yang seimbang:",options:["kurangi sampah di area yang bisa dikurangi, & terima bahwa sebagian kemasan memang perlu untuk keamanan","merasa gagal total lalu berhenti berusaha mengurangi sampah sama sekali dalam semua hal lain","memaksakan tidak memakai kemasan sama sekali meski risikonya bagi kesehatan & kebersihan cukup besar"],answer:0,explain:"Mengurangi sampah adalah soal pilihan bijak di banyak hal, bukan kesempurnaan mutlak di segala hal.",hint:"Kurangi yang bisa, terima yang memang perlu."},
{n:90,type:"mcq",micro:"Skenario: bank sampah sekolah",q:"Sekolahmu membuka bank sampah. Cara agar berjalan lancar:",options:["mengumpulkan sampah dari murid-murid tetapi tidak pernah menyalurkannya kepada pengepul mana pun","jadwal setor yang jelas, pencatatan tabungan transparan, & mitra pengepul yang tetap","membuka bank sampah sesekali saja tanpa jadwal tetap sehingga murid bingung kapan harus menyetor"],answer:1,explain:"Bank sampah butuh keteraturan & penyaluran yang pasti agar orang terus berpartisipasi.",hint:"Jadwal + catatan transparan + mitra tetap."},
{n:91,type:"mcq",micro:"Skenario: acara keluarga besar",q:"Keluarga besar akan berkumpul & biasanya menghasilkan banyak sampah kemasan & makanan. Usulan anak yang membantu:",options:["membiarkan saja semuanya berjalan seperti biasa karena itu urusan orang dewasa & bukan urusan anak","memakai semua peralatan makan sekali pakai supaya tidak ada yang perlu mencuci piring sesudahnya","usulkan masak secukupnya, pakai peralatan makan asli, sediakan wadah pilah, & bagikan sisa makanan layak"],answer:2,explain:"Anak pun bisa mengusulkan perubahan kecil yang mengurangi sampah acara keluarga.",hint:"Secukupnya + alat asli + pilah + bagikan sisa."},
{n:92,type:"open",micro:"Surat untuk sekolah",q:"Tulis usulan singkat kepada kepala sekolah tentang satu langkah konkret mengurangi sampah di sekolah, lengkap dengan alasannya.",explain:"Usulan yang jelas, beralasan, & menawarkan bantuan lebih mungkin ditindaklanjuti.",hint:"Satu langkah konkret + alasan + tawaran bantuan.",sample:"Kepada Bapak/Ibu Kepala Sekolah: kami mengusulkan pemasangan dua titik isi ulang air minum di sekolah & imbauan setiap murid membawa botol sendiri. Dari pengamatan kami selama seminggu, ada ratusan botol plastik dibuang tiap hari. Titik isi ulang akan sangat mengurangi sampah ini, menghemat uang jajan murid, & menjadikan sekolah contoh sekolah peduli lingkungan. Kami siap membantu sosialisasi."},
{n:93,type:"mcq",micro:"Skenario: label daur ulang membingungkan",q:"Kamu bingung apakah suatu kemasan bisa didaur ulang di daerahmu. Langkah yang masuk akal:",options:["cari tahu apa yang diterima bank sampah atau pengepul setempat, karena tidak semua daerah sama","menganggap semua jenis plastik pasti bisa didaur ulang di daerahmu tanpa perlu bertanya kepada siapa pun","membuang semuanya ke satu tempat sampah saja supaya tidak perlu repot mencari tahu lagi"],answer:0,explain:"Yang 'bisa didaur ulang' bergantung pada fasilitas setempat; mencari tahu membuat pemilahan kita berguna.",hint:"Cek apa yang diterima fasilitas setempat."},
{n:94,type:"tf",micro:"Kebiasaan sampah melatih warga",q:"Benar atau Salah: Kebiasaan mengurangi & memilah sampah sejak kecil membentuk warga dewasa yang ikut menjaga lingkungan & mendukung kebijakan yang baik.",answer:true,explain:"Kebiasaan hari ini adalah dasar sikap & pilihan sebagai warga di masa depan.",hint:"Kebiasaan kecil membentuk warga peduli."},
{n:95,type:"mcq",micro:"Skenario: teman meremehkan usahamu",q:"Teman berkata 'buat apa repot milah sampah, toh dicampur lagi di truk'. Responsmu:",options:["memarahi temanmu","cari tahu faktanya di daerahmu; di banyak tempat sampah terpilah memang disalurkan berbeda, & kalaupun belum, itu alasan mendorong perbaikan sistem, bukan menyerah","langsung berhenti memilah"],answer:1,explain:"Kekurangan sistem adalah alasan untuk memperbaikinya, bukan alasan untuk berhenti berbuat benar.",hint:"Cek fakta; dorong perbaikan, jangan menyerah."},
{n:96,type:"mcq",micro:"Tanda kamu makin bijak soal sampah",q:"Tanda kebiasaanmu berkembang:",options:["kamu makin sering memakai barang sekali pakai karena menurutmu itu lebih praktis dan cepat","kamu berhenti memikirkan soal sampah sama sekali karena merasa itu urusan orang dewasa saja","kamu lebih sering menolak yang tak perlu, membawa wadah sendiri, & tempat sampahmu lebih sedikit terisi"],answer:2,explain:"Pertumbuhan tampak dari pilihan konsumsi & jumlah sampah yang menurun.",hint:"Tolak, bawa wadah, sampah berkurang."},
{n:97,type:"mcq",micro:"Kebiasaan 3R sehari-hari",q:"Manakah kumpulan kebiasaan pengelolaan sampah yang baik?",options:["menolak yang tak perlu, membawa botol & tas sendiri, memilah, mengompos, menyetor ke bank sampah","memakai barang sekali pakai, mencampur semua jenis sampah, & membakar plastik di halaman rumah","membuang sampah ke selokan supaya cepat hilang dan terbawa air ke tempat yang jauh dari rumah"],answer:0,explain:"Kebiasaan kecil sehari-hari inilah yang menentukan seberapa banyak sampah yang kita bebankan ke lingkungan.",hint:"Tolak, bawa sendiri, pilah, kompos, setor."},
{n:98,type:"mcq",micro:"Saat ragu cara membuang sesuatu",q:"Aturan sederhana saat ragu bagaimana menangani sebuah barang bekas:",options:["simpan saja menumpuk di rumah tanpa pernah mengambil keputusan apa pun tentang barang itu","ikuti urutan: bisakah ditolak/dikurangi? dipakai ulang? diperbaiki? didaur ulang? baru terakhir dibuang dengan benar","langsung buang ke tempat sampah terdekat tanpa memikirkan apakah barang itu masih berguna atau tidak"],answer:1,explain:"Menerapkan hierarki 3R pada tiap barang membantu mengambil keputusan yang paling ramah lingkungan.",hint:"Tolak > pakai ulang > perbaiki > daur ulang > buang."},
{n:99,type:"mcq",micro:"Mengajari yang lebih muda",q:"Cara membantu adik memahami pengelolaan sampah:",options:["menakut-nakutinya dengan cerita bahwa bumi akan segera hancur, melarangnya menyentuh sampah apa pun, & menyuruhnya menurut saja tanpa penjelasan","membiarkannya membuang sampah di mana saja agar belajar sendiri, & memarahinya setiap kali ia salah memilah sampah di depan semua anggota keluarga","ajak ia memilah sampah jadi permainan, tunjukkan kompos & tanaman yang tumbuh darinya, & contohkan membawa botol sendiri"],answer:2,explain:"Anak belajar kebiasaan lingkungan lewat pengalaman menyenangkan & teladan, bukan rasa takut.",hint:"Jadikan permainan + tunjukkan hasil + contohkan."},
{n:100,type:"mcq",micro:"Sintesis",q:"Inti dari 'Sampah, Daur Ulang & 3R' adalah...",options:["sampah paling baik diatasi dengan tidak menghasilkannya: kurangi & pakai ulang lebih dulu, daur ulang & kompos bila bisa, pilah dari sumber, & buang dengan benar hanya sebagai jalan terakhir","daur ulang sudah cukup menyelesaikan semua masalah sampah, sehingga kita boleh memakai & membuang barang sesuka hati, dan setelah dibuang ke tempat sampah masalahnya dianggap selesai","yang terpenting sampah sudah diangkut petugas dari rumah, dan urusan memilah, mengompos, atau mengurangi konsumsi sepenuhnya menjadi tanggung jawab pemerintah & pemulung saja"],answer:0,explain:"Hierarki 3R, pemilahan dari sumber, & kebiasaan konsumsi yang sadar bersama-sama mengurangi beban sampah pada lingkungan & masyarakat.",hint:"Kurangi & pakai ulang dulu; buang jalan terakhir."},
];
